,"item_kind":"exercise","instructions":"לעמוד על הגומייה, גו כפוף קדימה מעט, ולפתוח את הידיים לצדדים.","instruction_steps":["לעמוד על הגומייה, גו כפוף קדימה מעט, ולפתוח את הידיים לצדדים."],"safety_notes":"כאב עד 3/10 בזמן התרגיל מקובל אם הוא חולף תוך 24 שעות. יש להפסיק בכאב חד, נימול או הקרנה.","default_prescription":{"mode":"reps","sets":3,"reps":12,"rest_sec":45}}},{"id":"0721","region_slug":"wrist_hand","patch":{"name":"מתיחת שורש כף היד לצד","name_en":"Side Wrist Pull Stretch","aliases":["side wrist pull stretch"],"item_kind":"exercise","instructions":"להושיט זרוע קדימה ולמשוך את כף היד בעדינות לצד.","instruction_steps":["להושיט זרוע קדימה ולמשוך את כף היד בעדינות לצד."],"safety_notes":"כאב עד 3/10 בזמן התרגיל מקובל אם הוא חולף תוך 24 שעות. יש להפסיק בכאב חד, נימול או הקרנה.","default_prescription":{"mode":"hold","sets":3,"hold_sec":25,"rest_sec":15}}}]$enrich_json$::jsonb;
  v_row JSONB;
  v_ext_ref TEXT;
  v_id UUID;
  v_patch JSONB;
  v_region UUID;
  v_res JSONB;
  v_applied INT := 0;
  v_skipped JSONB := '[]'::jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM app."user" WHERE id = v_curator) THEN
    RETURN jsonb_build_object('applied', 0, 'skipped', '[]'::jsonb, 'note', 'no curator user on this database');
  END IF;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_data) LOOP
    v_ext_ref := v_row ->> 'id';
    SELECT id INTO v_id FROM app.exercise WHERE external_ref = v_ext_ref AND clinic_id IS NULL AND deleted_at IS NULL;
    IF v_id IS NULL THEN
      CONTINUE; -- dataset row not ingested yet on this pass (scripts/ingest-exercises.ts is a separate manual step)
    END IF;
    SELECT id INTO v_region FROM app.body_region WHERE slug = (v_row ->> 'region_slug');
    v_patch := (v_row -> 'patch') || jsonb_build_object('body_region_id', v_region);
    v_res := app.catalog_save_exercise(v_curator, v_id, v_patch, NULL);
    IF v_res ? 'error' THEN
      v_skipped := v_skipped || jsonb_build_object('id', v_id, 'external_ref', v_ext_ref, 'reason', COALESCE(v_res ->> 'message', v_res ->> 'error'));
    ELSE
      v_applied := v_applied + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('applied', v_applied, 'skipped', v_skipped);
END;
$$ LANGUAGE plpgsql;

SELECT app._catalog_apply_dataset_enrichment_2026_09_13();
